<?php
namespace App\Http\Resources; use Illuminate\Http\Request; use Illuminate\Http\Resources\Json\JsonResource;
class WorkSessionResource extends JsonResource { public function toArray(Request $request):array{return ['id'=>$this->id,'uuid'=>$this->uuid,'offline_uuid'=>$this->uuid,'user_id'=>$this->user?->uuid,'salesman_id'=>$this->salesman_id,'device_id'=>$this->device?->uuid,'date'=>$this->date?->format('Y-m-d'),'status'=>$this->status,'started_at'=>$this->start_time?->toISOString(),'ended_at'=>$this->end_time?->toISOString(),'duration_minutes'=>$this->duration_minutes,'duration_hours'=>$this->duration_minutes===null?null:round($this->duration_minutes/60,2),'start_location'=>['latitude'=>$this->start_latitude,'longitude'=>$this->start_longitude,'accuracy'=>$this->start_accuracy],'end_location'=>$this->end_time?['latitude'=>$this->end_latitude,'longitude'=>$this->end_longitude,'accuracy'=>$this->end_accuracy]:null,'is_late_start'=>(bool)$this->is_late_start,'is_early_finish'=>(bool)$this->is_early_finish];} }
